import assert from 'node:assert/strict';
const ok=async(response,status=200)=>{assert.equal(response.status,status,await response.clone().text());return response.json();};
export async function exercisePropertyConversion({request,owner,member,restart}){
 const base='/api/content/workspaces/conversion-workspace',imported=await ok(await request(base+'/imports',{method:'POST',account:owner,body:{expectedRevision:0,importId:'conversion-http-import',pages:[{sourceId:'container',parentSourceId:null,title:'Fictional CSV',blocks:[]},...Array.from({length:3},(_,index)=>({sourceId:'page-'+index,parentSourceId:'container',title:'Row '+index,blocks:[]}))],collections:[{sourceId:'source',pageSourceId:'container',properties:[{id:'amount',name:'Amount',type:'text'},{id:'date',name:'Date',type:'text'}],records:[['12.50','2024-02-29'],['0','2026-10-16'],['','']].map(([amount,date],index)=>({sourceId:'row-'+index,pageSourceId:'page-'+index,values:{amount,date}}))}]}}),201);assert.equal(imported.revision,1);
 const listing=await ok(await request(base+'/collections',{account:owner})),id=listing.collections[0].id,path=base+'/collections/'+id,initial=await ok(await request(path,{account:owner})),[amount,date]=initial.collection.properties,conversion=path+'/property-conversions',input={expectedRevision:1,sourcePropertyId:amount.id,targetType:'number',name:'Number copy'};
 assert.equal((await request(conversion+'/preview',{method:'POST',account:member,body:input})).status,404);assert.equal((await request(conversion+'/preview',{method:'POST',account:owner,headers:{'X-Yumunio-Expected-Account':member.id},body:input})).status,404);assert.equal((await request(conversion+'/preview',{method:'POST',account:owner,headers:{Origin:'https://outside.fixture.invalid'},body:input})).status,403);
 const preview=await ok(await request(conversion+'/preview',{method:'POST',account:owner,body:input}));assert.equal(preview.valid,true);assert.deepEqual(preview.rows.map(row=>row.value),[12.5,0,null]);assert.equal((await request(conversion,{method:'POST',account:owner,body:{...input,previewDigest:preview.previewDigest,confirm:false}})).status,409);
 const row=initial.collection.records[1],recordPath=path+'/records/'+row.id;await ok(await request(recordPath,{method:'PATCH',account:owner,body:{expectedRevision:1,values:{[amount.id]:'001'}}}));assert.equal((await request(conversion,{method:'POST',account:owner,body:{...input,previewDigest:preview.previewDigest,confirm:true}})).status,409);
 input.expectedRevision=2;const invalid=await ok(await request(conversion+'/preview',{method:'POST',account:owner,body:input}));assert.equal(invalid.valid,false);assert.equal(invalid.invalidCount,1);assert.equal((await request(conversion,{method:'POST',account:owner,body:{...input,previewDigest:invalid.previewDigest,confirm:true}})).status,409);assert.equal((await ok(await request(path,{account:owner}))).revision,2);
 await ok(await request(recordPath,{method:'PATCH',account:owner,body:{expectedRevision:2,values:{[amount.id]:'7'}}}));input.expectedRevision=3;const current=await ok(await request(conversion+'/preview',{method:'POST',account:owner,body:input})),saved=await ok(await request(conversion,{method:'POST',account:owner,body:{...input,previewDigest:current.previewDigest,confirm:true}}));assert.equal(saved.revision,4);assert.notEqual(saved.propertyId,amount.id);assert.equal((await request(conversion,{method:'POST',account:owner,body:{...input,previewDigest:current.previewDigest,confirm:true}})).status,409);
 const dateInput={expectedRevision:4,sourcePropertyId:date.id,targetType:'date',name:'Date copy'},datePreview=await ok(await request(conversion+'/preview',{method:'POST',account:owner,body:dateInput})),dateSaved=await ok(await request(conversion,{method:'POST',account:owner,body:{...dateInput,previewDigest:datePreview.previewDigest,confirm:true}}));assert.equal(dateSaved.revision,5);
 await restart();const final=await ok(await request(path,{account:owner}));assert.equal(final.revision,5);assert.equal(final.collection.properties.length,4);assert.deepEqual(final.collection.sourceProperties,initial.collection.properties);assert.equal(final.collection.records[1].values[amount.id],'7');assert.equal(final.collection.records[1].values[saved.propertyId],7);assert.equal(final.collection.records[1].sourceValues[amount.id],'0');assert.equal(final.collection.records[0].values[dateSaved.propertyId],'2024-02-29');assert.equal(final.collection.records[2].values[dateSaved.propertyId],null);assert.equal((await request(path,{account:member})).status,404);
 const exported=await ok(await request(base+'/export?format=json',{account:owner}));assert.deepEqual(exported.collections[0].collection.properties,final.collection.properties);assert.equal(exported.collections[0].collection.records[1].values[saved.propertyId],7);assert.equal(exported.collections[0].collection.records[1].sourceValues[amount.id],'0');
}
